def has_dup_slow(items):
    steps = 0
    for i in range(len(items)):
        for j in range(i + 1, len(items)):
            steps += 1
            if items[i] == items[j]:
                return True, steps
    return False, steps


def has_dup_fast(items):
    seen = set()
    steps = 0
    for x in items:
        steps += 1
        if x in seen:
            return True, steps
        seen.add(x)
    return False, steps


print(has_dup_slow([4, 7, 1, 7, 9]))
print(has_dup_fast([4, 7, 1, 7, 9]))
print(has_dup_slow([5, 6, 7, 8]))
print(has_dup_fast([5, 6, 7, 8]))
